/bin/bash -lc "cd /workspace && python3 - << 'PY'
import os, openai_client as m

# missing key raises
os.environ.pop(\"OPENAI_API_KEY\", None)
try:
    m.ResponsesClient()
except m.OpenAIError as e:
    print(\"missing-key OK:\", str(e)[:40])

# extraction helper
sample = {
    \"output\": [
        {\"content\": [{\"type\": \"output_text\", \"text\": \"Hello\"}, {\"type\": \"output_text\", \"text\": \" world\"}]}
    ]
}
print(\"extract:\", repr(m.ResponsesClient._extract_output_text(sample)))

# convenience with a fake client (no network)
c = m.ResponsesClient(api_key=\"fake\")
print(\"base_url:\", c._base_url)
PY"

